package io.knowledgebrain.collaboration;
import java.util.*;import java.time.*;import java.nio.charset.StandardCharsets;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
import org.springframework.mock.web.MockHttpServletRequest;import org.springframework.web.server.ResponseStatusException;
import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
class ResubmissionRequestApiTest {
 SubmissionApiTest f;ResubmissionRequestStore store;ResubmissionRequestController api;
 @BeforeEach void setup(){f=new SubmissionApiTest();f.setup();store=mock(ResubmissionRequestStore.class);api=new ResubmissionRequestController(store,f.f.api,new SimpleMeterRegistry());}
 MockHttpServletRequest req(String method,String content){var r=f.req(method,content);r.removeHeader("If-Match");r.addHeader("If-Match","\"rr0\"");return r;}
 String input(){return "{\"action\":\"REQUEST\",\"reason\":\"Feedback\",\"submissionVersion\":1,\"assignmentVersion\":2}";}
 ResubmissionRequestStore.Request value(){return new ResubmissionRequestStore.Request(f.f.id,f.f.id,f.assignment,f.study,f.f.group,f.f.space,f.f.actor,f.f.actor,f.f.actor,1,1,2,"Feedback","REQUESTED",null,"AUTHOR_AND_OWNER",Instant.now().toString(),Instant.now().toString());}
 void status(int code,org.junit.jupiter.api.function.Executable action){assertEquals(code,assertThrows(ResponseStatusException.class,action).getStatusCode().value());}
 Object change(MockHttpServletRequest r)throws Exception{return api.change(f.f.group.toString(),f.study.toString(),f.assignment.toString(),f.f.id.toString(),r);}
 @Test void onlyCurrentOwnerWritesUsingAuthenticatedActorAndIndependentEtag()throws Exception{var v=value();when(store.change(eq(f.f.group),eq(f.f.space),eq(f.study),eq(f.assignment),eq(f.f.id),eq(f.f.actor),eq(0L),eq(new ResubmissionRequestInput("REQUEST","Feedback",1,2)),anyString())).thenReturn(v);var response=api.change(f.f.group.toString(),f.study.toString(),f.assignment.toString(),f.f.id.toString(),req("PUT",input()));assertEquals("\"rr1\"",response.getHeaders().getETag());assertEquals("no-store",response.getHeaders().getCacheControl());verify(store).change(eq(f.f.group),eq(f.f.space),eq(f.study),eq(f.assignment),eq(f.f.id),eq(f.f.actor),eq(0L),any(),anyString());}
 @Test void memberAndViewerCannotWriteFeedback(){for(var role:List.of("MEMBER","VIEWER")){f.f.role(role);status(403,()->change(req("PUT",input())));}verifyNoInteractions(store);}
 @Test void nonOwnerReadAndHistoryAreAuthorScopedWithoutWriteOrigin()throws Exception{f.f.role("VIEWER");when(store.get(f.f.group,f.f.space,f.study,f.assignment,f.f.id,f.f.actor,false)).thenReturn(new ResubmissionRequestStore.View(1,2,null,false,false));var r=req("GET",null);r.removeHeader("Origin");var response=api.get(f.f.group.toString(),f.study.toString(),f.assignment.toString(),f.f.id.toString(),r);assertEquals("\"rr0\"",response.getHeaders().getETag());api.history(f.f.group.toString(),f.study.toString(),f.assignment.toString(),f.f.id.toString(),req("GET",null));verify(store).get(f.f.group,f.f.space,f.study,f.assignment,f.f.id,f.f.actor,false);verify(store).history(f.f.group,f.f.space,f.study,f.assignment,f.f.id,f.f.actor,false,Long.MAX_VALUE,5);}
 @Test void ownerReadUsesExistingOwnerVisibilityWithoutGrantingActorSelectors()throws Exception{when(store.get(f.f.group,f.f.space,f.study,f.assignment,f.f.id,f.f.actor,true)).thenReturn(new ResubmissionRequestStore.View(1,2,value(),true,true));var r=req("GET",null);r.removeHeader("Origin");assertEquals(200,api.get(f.f.group.toString(),f.study.toString(),f.assignment.toString(),f.f.id.toString(),r).getStatusCode().value());verify(store).get(f.f.group,f.f.space,f.study,f.assignment,f.f.id,f.f.actor,true);var query=req("GET",null);query.addParameter("authorId",f.f.actor.toString());status(400,()->api.get(f.f.group.toString(),f.study.toString(),f.assignment.toString(),f.f.id.toString(),query));}
 @Test void strictExactJsonTextAndIntegralVersionsRejectForgedFields(){for(String value:List.of("{}",input()+" {}",input().replace("Feedback",""),input().replace("Feedback","\\u0000"),input().replace("Feedback","\\ud800"),input().replace("Feedback","x".repeat(8193)),input().replace("submissionVersion\":1","submissionVersion\":1.0"),input().replace("submissionVersion\":1","submissionVersion\":0"),input().replace("assignmentVersion\":2","assignmentVersion\":9223372036854775808"),input().replace("}",",\"reviewerId\":\"spoof\"}"),input().replace("}",",\"reason\":\"Duplicate\"}"))){status(400,()->change(req("PUT",value)));}verifyNoInteractions(store);}
 @Test void requiresStrongFeedbackVersionAndBoundedExactQuery(){var missing=req("PUT",input());missing.removeHeader("If-Match");status(428,()->change(missing));for(var tag:List.of("*","W/\"rr0\"","\"su1\"","\"rr01\"","\"rr9999999999999999999\"")){var r=req("PUT",input());r.removeHeader("If-Match");r.addHeader("If-Match",tag);status(400,()->change(r));}var duplicate=req("PUT",input());duplicate.addHeader("If-Match","\"rr0\"");status(400,()->change(duplicate));var limit=req("GET",null);limit.addParameter("limit","11");status(400,()->api.history(f.f.group.toString(),f.study.toString(),f.assignment.toString(),f.f.id.toString(),limit));var body=req("GET","{}");status(400,()->api.get(f.f.group.toString(),f.study.toString(),f.assignment.toString(),f.f.id.toString(),body));verifyNoInteractions(store);}
 @Test void malformedCredentialOriginAndRemovedMembershipNeverReachPersistence(){var insecure=req("PUT",input());insecure.setSecure(false);var duplicate=req("PUT",input());duplicate.addHeader("Cookie","__Host-brain_guest="+f.f.token);var cross=req("PUT",input());cross.removeHeader("Origin");cross.addHeader("Origin","https://elsewhere.invalid");for(var r:List.of(insecure,duplicate,cross))assertThrows(ResponseStatusException.class,()->change(r));verifyNoInteractions(store);when(f.f.auth.participation(any(),anyList(),anyString())).thenReturn(new GroupSpaceClient.Access(f.f.actor,"REGISTERED",List.of()));status(404,()->api.get(f.f.group.toString(),f.study.toString(),f.assignment.toString(),f.f.id.toString(),req("GET",null)));verifyNoInteractions(store);}
 @Test void validUnicodeByteBoundaryAndBodyLimitAreExplicit(){assertDoesNotThrow(()->ResubmissionRequestInput.validate(new ResubmissionRequestInput("REQUEST","가".repeat(2730)+"ab",1,2)));assertThrows(ResponseStatusException.class,()->ResubmissionRequestInput.validate(new ResubmissionRequestInput("REQUEST","가".repeat(2731),1,2)));status(413,()->change(req("PUT"," ".repeat(20481))));var type=req("PUT",input());type.setContentType("text/plain");status(415,()->change(type));verifyNoInteractions(store);}
 @Test void cancelHasExactCommandShapeAndUsesCurrentOwner()throws Exception{var v=value();when(store.change(any(),any(),any(),any(),any(),any(),eq(0L),eq(new ResubmissionRequestInput("CANCEL",null,0,0)),anyString())).thenReturn(v);assertEquals(200,api.change(f.f.group.toString(),f.study.toString(),f.assignment.toString(),f.f.id.toString(),req("PUT","{\"action\":\"CANCEL\"}")).getStatusCode().value());for(var b:List.of("{\"action\":\"RESOLVED\"}","{\"action\":\"CANCEL\",\"reason\":\"hidden\"}","{\"action\":\"CANCEL\",\"actorId\":\"spoof\"}"))status(400,()->change(req("PUT",b)));}
}
